class Solution {
  public long maxProduct(int[] nums) {
    int n = nums.length;
    Integer[] idx = new Integer[n];
    for (int i = 0; i < n; i++) idx[i] = i;
    java.util.Arrays.sort(idx, (a, b) -> Integer.compare(nums[a], nums[b]));
    java.util.TreeSet<Integer> pick = new java.util.TreeSet<>();
    for (int i = 0; i < Math.min(4, n); i++) {
      pick.add(idx[i]);
      pick.add(idx[n - 1 - i]);
    }
    Integer[] cand = pick.toArray(new Integer[0]);
    long maxPair = Long.MIN_VALUE, minPair = Long.MAX_VALUE;
    for (int i = 0; i < cand.length; i++) {
      for (int j = i + 1; j < cand.length; j++) {
        long p = (long) nums[cand[i]] * nums[cand[j]];
        maxPair = Math.max(maxPair, p);
        minPair = Math.min(minPair, p);
      }
    }
    return 100_000L * Math.max(maxPair, -minPair);
  }
}
